BEGIN;

UPDATE public.questions q
SET question_text = '新しい勉強法を試したクラス20人と、試していないクラス20人の平均点をt検定で比べた（前セットで扱った場面）。このt検定のような検定を使うとき、データについてこっそり置いている前提はどれ？',
    options = '["点数の分布が、山がひとつで左右対称に近い「正規分布」に沿っていること", "2つのクラスの人数が、最初から最後まで1人残らずぴったり同じであること", "点数の範囲が、テストの配点にかかわらず必ず0点から100点までに収まること", "2つのクラスの平均点が、検定を始める前からあらかじめほとんど同じであること"]'::jsonb,
    explanation_data = '{"asked": "t検定のようなパラメトリック検定が、データについてあらかじめ置いている前提は何か。", "point": "パラメトリック検定は「データが正規分布に近い形をしている」ことを前提にして計算式を組み立てている。", "kid": "パラメトリック検定は、点数を集めるとだいたい真ん中が一番多くて、両端に行くほど少なくなる「山型」に散らばるはずだ、という思い込みのうえに計算式ができている。", "eg": "身長のようにたくさんの人を集めると、平均くらいの身長の人が一番多くて、すごく高い人・すごく低い人はだんだん少なくなる山型になる。t検定は、点数もこの身長のような山型に散らばっていることを当てにして計算している。", "terms": [["パラメトリック検定", "データが正規分布のような決まった形に従うと仮定して行う検定。t検定・分散分析など"], ["正規分布", "真ん中が一番多く、両端に行くほど少なくなる、左右対称の山型の散らばり方"]], "think": "なぜ「前提」という言葉を使うのかがカギ。t検定の計算式は、平均や標準偏差を使ってp値を出す。この計算式は、データが正規分布のような山型に散らばっているときにだけ正しく機能するように作られている。データの散らばり方が前提と大きく違っていると、計算式自体は数字を返すが、その数字（p値）の意味が保証されなくなる。だから使う前に「この前提が成り立っていそうか」を確かめる必要がある。", "vs": "「クラスの人数が同じ」「点数が0〜100点」「2群の平均が近い」はどれも検定の前提ではなく、たまたま今回の場面にありそうな条件にすぎない。前提として本当に効いてくるのは、分布の形（正規分布に近いか）のほう。", "why_asked": "この前提を知らないまま検定を使うと、「t検定さえ使えばどんなデータでも正しい結論が出る」と誤解してしまう。次の問いで、この前提が崩れたときにどうするかを学ぶための土台になる。", "usecase": "アンケートの回答やテストの点数を検定にかける前に、ヒストグラムを描いて山型に近いかをまず目で確認する、という実務上の一手間につながる。", "opt": ["正解。t検定などのパラメトリック検定は、データが正規分布のような山型に近いことを前提に計算式が組まれている。", "人数がぴったり同じかどうかは検定の前提ではない。人数が違っても使える検定はある。", "点数の範囲が0〜100点かどうかは前提にならない。テストの点数以外（体重・時間など）でも同じ検定を使う。", "2群の平均が近いかどうかはこれから検定で確かめたいことであって、あらかじめ置いておく前提ではない。"], "viz": "<svg viewBox=\"0 0 340 138\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">t検定などが当てにしている散らばり方</text><line x1=\"30\" y1=\"100\" x2=\"310\" y2=\"100\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><path d=\"M60,100 Q170,30 280,100 Z\" fill=\"#3b82f6\" opacity=\"0.18\"/><path d=\"M60,100 Q170,30 280,100\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"2\"/><text x=\"170\" y=\"118\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">真ん中が多く、両端が少ない「山型」＝正規分布</text><text x=\"170\" y=\"132\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">この形に近いことが、t検定の前提</text></svg>"}'::jsonb
FROM public.subjects s
WHERE q.subject_id = s.id
  AND s.slug = 'stats-basics'
  AND q.source_ref = 'stats12-q01';

UPDATE public.questions q
SET question_text = '5人の年収（万円）が 300, 320, 340, 360, 5000 のとき、平均は1264万円になり、実際の5人のほとんどの感覚(300〜360万円)からかけ離れる。一方、中央値は340万円で、5000万円という外れ値の影響をあまり受けない。ノンパラメトリック検定が外れ値に強いのは、これと同じどんな理由から？',
    options = '["値そのものでなく順位に変換するので、極端な値の大きさが計算に反映されにくくなるから", "計算の前に外れ値を自動的に見つけて、こっそり除外する仕組みが入っているから", "サンプルの人数を、外れ値がある分だけ自動的に多めに数え直す仕組みがあるから", "外れ値がある場合だけ、有意水準を5%から1%へと自動的に厳しく変える仕組みがあるから"]'::jsonb,
    explanation_data = '{"asked": "ノンパラメトリック検定が外れ値の影響を受けにくいのは、どういう仕組みによるものか。", "point": "中央値が「順番の真ん中」しか見ないのと同じく、ノンパラメトリック検定も値の大きさではなく順位しか見ないので、外れ値の影響が抑えられる。", "kid": "中央値は5000万円の人がいても「一番大きい人」という順番の情報しか使わないので、1264万円まで引きずられた平均ほどは動かない。ノンパラメトリック検定も同じように、値の大きさそのものではなく順位を使うので、極端な値に振り回されにくい。", "eg": "運動会の順位発表で、1位の子が他の子よりどれだけ速かったか(タイム差)は発表されず、「1位」というひとことで終わる。タイム差がどれだけ開いていても、発表される情報は「1位」という同じ1つの席なので、極端な速さが目立ちすぎることがない。", "terms": [["中央値", "データを大きさの順に並べたとき、ちょうど真ん中に来る値"], ["ロバスト性", "外れ値のような極端な値があっても、結果が大きく変わりにくい性質"]], "think": "なぜ順位に変換すると外れ値に強くなるのかがカギ。平均は「5000万円」という値の大きさをそのまま合計に足し込むので、この1つの値がとても大きいと合計、ひいては平均を大きく引き上げてしまう。中央値は値の大きさを見ず、「大きい順に並べたとき真ん中は何番目か」という順位だけを見るので、5000万円がどれだけ極端に大きくても「一番大きい」という1つの順位としてしか扱われず、真ん中の値にはほとんど影響しない。ノンパラメトリック検定も同じ仕組みで、q03で見たとおり値を順位に変換してから計算するので、極端な値の「大きさ」そのものは検定の結果にほとんど効かなくなる。", "vs": "「外れ値を自動的に除外する」「人数を数え直す」「有意水準を自動的に変える」は、いずれもノンパラメトリック検定が実際にやっていることではない。データを削ったり検定のルールをこっそり変えたりするのではなく、値の使い方(順位に変換する)を変えているだけ。", "why_asked": "「なぜノンパラメトリック検定は外れ値に強いのか」という理由を知らずに丸暗記していると、平均と中央値の話(データのようすの基礎編)とのつながりに気づけない。同じ「順位を使う・使わない」という発想が形を変えて出てきているだけだと分かると、理解がつながる。", "usecase": "所得・待ち時間・売上のように一部だけ極端に大きい(小さい)値が混じりやすいデータを扱うとき、平均や通常の検定の代わりに中央値やノンパラメトリック検定を選ぶ判断の理由になる。", "opt": ["正解。値そのものでなく順位に変換するので、極端な値の大きさが計算にそのまま反映されにくくなる。中央値が外れ値に強いのと同じ発想。", "外れ値を自動的に見つけて除外する仕組みは無い。ノンパラメトリック検定は外れ値も含めた全員を順位に変換して使う。", "サンプルの人数を外れ値の分だけ多く数え直す仕組みは無い。人数はそのまま、値の扱い方(順位への変換)だけが変わる。", "有意水準を外れ値の有無で自動的に変える仕組みは無い。有意水準は検定の前にあらかじめ決めておく別の値。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">平均と中央値、5000万円にどれだけ引きずられる？</text><line x1=\"30\" y1=\"48\" x2=\"310\" y2=\"48\" stroke=\"#2a2f3f\"/><circle cx=\"45\" cy=\"48\" r=\"4\" fill=\"#3b82f6\"/><circle cx=\"65\" cy=\"48\" r=\"4\" fill=\"#3b82f6\"/><circle cx=\"85\" cy=\"48\" r=\"4\" fill=\"#3b82f6\"/><circle cx=\"105\" cy=\"48\" r=\"4\" fill=\"#3b82f6\"/><circle cx=\"290\" cy=\"48\" r=\"5\" fill=\"#c47070\"/><text x=\"290\" y=\"38\" fill=\"#c47070\" font-size=\"8.5\" text-anchor=\"middle\">5000万円</text><polygon points=\"210,50 202,66 218,66\" fill=\"#c47070\"/><text x=\"210\" y=\"80\" fill=\"#c47070\" font-size=\"9\" text-anchor=\"middle\">平均1264万円</text><text x=\"210\" y=\"92\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">大きく引きずられる</text><polygon points=\"85,50 77,66 93,66\" fill=\"#6ab08d\"/><text x=\"85\" y=\"80\" fill=\"#6ab08d\" font-size=\"9\" text-anchor=\"middle\">中央値340万円</text><text x=\"85\" y=\"92\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">ほぼ動かない</text><text x=\"170\" y=\"120\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">順位しか見ないので、大きさに引きずられない</text></svg>"}'::jsonb
FROM public.subjects s
WHERE q.subject_id = s.id
  AND s.slug = 'stats-basics'
  AND q.source_ref = 'stats12-q09';

UPDATE public.questions q
SET question_text = 'ここまでの内容をまとめる。パラメトリック検定とノンパラメトリック検定のどちらを使うべきかを判断するとき、まず確認すべき組み合わせとして最も適切なのはどれ？',
    options = '["データの分布の形（正規分布に近いか）、標本の大きさ、データの尺度（数値か順位か）", "検定をしたあとに出てくるp値の大きさ、効果量、信頼区間の幅", "有意水準をいくつに設定したか、片側検定か両側検定か、帰無仮説の文章の長さ", "データを集めるのにかかった日数、入力に使ったソフトの種類、ファイル形式（csvかどうか）"]'::jsonb,
    explanation_data = '{"asked": "パラメトリック検定とノンパラメトリック検定、どちらを選ぶかの判断基準のまとめ。", "point": "分布の形・標本サイズ・尺度の3つを確認して、正規分布に近く数値データで標本もある程度あればパラメトリック、そうでなければノンパラメトリックを選ぶ。", "kid": "どちらの検定を使うか迷ったら、①点数の散らばりが山型(正規分布)に近いか、②集めた人数が十分多いか、③データが数値なのか、それとも順位や順番しか意味を持たないデータなのか、の3つを確認する。", "eg": "服のサイズを選ぶときに「身長」「体型」「用途」の3つを見て決めるのと同じで、検定選びも1つの基準だけでなく、分布の形・標本の大きさ・尺度の3つを合わせて確認して決める。", "terms": [["標本サイズ", "検定に使うデータの人数（個数）"], ["尺度", "データの測り方の種類。数値そのものが意味を持つデータもあれば、順位や順序しか意味を持たないデータもある"]], "think": "なぜこの3つを確認するのかがカギ。q01で見たとおり、パラメトリック検定は正規分布に近いことを前提にしている。データが山型に近くない、あるいは満足度アンケートのように順位しか意味を持たない尺度なら、その前提がそもそも成り立たないので、q02〜q08で見たノンパラメトリック検定を選ぶことになる。また標本サイズが少ないと「本当に正規分布に近いのか」自体を確かめにくいため、標本が小さいときは前提を置かずに済むノンパラメトリック検定のほうが安全な選択になりやすい。分布の形・標本サイズ・尺度という3つの確認を飛ばして「いつものt検定」を機械的に使ってしまうと、q01で確認した前提が崩れたまま検定をかけることになり、出てきたp値の意味が保証されなくなる。", "vs": "p値・効果量・信頼区間の幅は、検定を行ったあとに出てくる結果であり、検定を選ぶ前の基準にはならない。有意水準や片側・両側の違いは、検定の種類を選んだ「あと」に決める設定であり、パラメトリックかノンパラメトリックかを選ぶ基準そのものではない。データを集めた日数やソフトの種類、ファイル形式も、データそのものの性質とは無関係な事情。", "why_asked": "この問題集で学んだ検定を実際の場面で使うとき、名前を覚えているだけでは足りず、「どちらを選ぶべきか」を自分で判断できる必要がある。ここまでの用語(正規分布・標本・尺度)をつなげて判断基準にできるかを確かめる、このセットのまとめの問い。", "usecase": "実際にデータを集めて検定を選ぶとき、まずヒストグラムで分布の形を確認し、人数と尺度をあわせて見て、パラメトリック検定とノンパラメトリック検定のどちらを使うかを決める、という実務の手順そのものになる。", "opt": ["正解。分布の形・標本サイズ・尺度の3つを確認して、パラメトリックとノンパラメトリックのどちらを使うか判断する。", "p値・効果量・信頼区間の幅は、検定を行ったあとに出てくる結果であって、検定の前にデータの性質から確認しておく基準ではない。", "有意水準や片側・両側の違いは、検定の種類を選んだあとに決める設定であり、検定の種類そのものを選ぶ基準ではない。", "データを集めた日数やソフトの種類、ファイル形式は、データそのものの性質とは関係のない事情で、検定選びの基準にはならない。"], "viz": "<svg viewBox=\"0 0 340 148\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">検定選びの3つの確認ポイント</text><rect x=\"20\" y=\"28\" width=\"90\" height=\"40\" fill=\"none\" stroke=\"#2a2f3f\" rx=\"4\"/><text x=\"65\" y=\"46\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">分布の形</text><text x=\"65\" y=\"60\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">正規分布に近い？</text><rect x=\"125\" y=\"28\" width=\"90\" height=\"40\" fill=\"none\" stroke=\"#2a2f3f\" rx=\"4\"/><text x=\"170\" y=\"46\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">標本サイズ</text><text x=\"170\" y=\"60\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">人数は十分？</text><rect x=\"230\" y=\"28\" width=\"90\" height=\"40\" fill=\"none\" stroke=\"#2a2f3f\" rx=\"4\"/><text x=\"275\" y=\"46\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">尺度</text><text x=\"275\" y=\"60\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">数値？順位？</text><line x1=\"170\" y1=\"68\" x2=\"170\" y2=\"84\" stroke=\"#8892a4\"/><rect x=\"30\" y=\"88\" width=\"120\" height=\"32\" fill=\"#3b82f6\" opacity=\"0.25\" rx=\"4\"/><text x=\"90\" y=\"102\" fill=\"#e8eaf0\" font-size=\"8.5\" text-anchor=\"middle\">前提を満たす</text><text x=\"90\" y=\"114\" fill=\"#60a5fa\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">パラメトリック検定</text><rect x=\"190\" y=\"88\" width=\"120\" height=\"32\" fill=\"#c9a04a\" opacity=\"0.25\" rx=\"4\"/><text x=\"250\" y=\"102\" fill=\"#e8eaf0\" font-size=\"8.5\" text-anchor=\"middle\">前提が崩れている</text><text x=\"250\" y=\"114\" fill=\"#c9a04a\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">ノンパラメトリック検定</text><text x=\"170\" y=\"136\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">3つの確認結果で、どちらを選ぶか決まる</text></svg>"}'::jsonb
FROM public.subjects s
WHERE q.subject_id = s.id
  AND s.slug = 'stats-basics'
  AND q.source_ref = 'stats12-q10';

COMMIT;
